<script setup lang="ts">
import {acquireInert} from "../services/inertLease"
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
const props=defineProps<{title:string;current:string;scopes:Array<{key:string;label:string}>;scope:string;targets:Array<{uid:string;label:string;disabled?:boolean}>;target:string;busy:boolean;errors:string[];impact:string;recent?:Array<{uid:string;label:string}>;canCreate?:boolean;submitLabel?:string}>()
const emit=defineEmits<{scope:[value:string];target:[value:string];submit:[];close:[];create:[name:string];clearRecent:[]}>()
const query=ref(''),name=ref(''),panel=ref<HTMLElement>(),search=ref<HTMLInputElement>()
const visible=computed(()=>props.targets.filter(row=>row.label.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
let root:HTMLElement|null=null,origin:HTMLElement|null=null,releaseInert=()=>{},overflow=''
function close(){if(!props.busy)emit('close')}
function keyboard(event:KeyboardEvent){if(event.isComposing)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();close();return}if(event.key==='Tab'&&panel.value){const nodes=[...panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(row=>row.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(!first){event.preventDefault();panel.value.focus()}else if(!panel.value.contains(document.activeElement)||document.activeElement===panel.value){event.preventDefault();(event.shiftKey?last:first)?.focus()}else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
onMounted(async()=>{root=document.querySelector('#app');releaseInert=acquireInert(root);origin=document.activeElement instanceof HTMLElement?document.activeElement:null;overflow=document.body.style.overflow;document.body.style.overflow='hidden';document.addEventListener('keydown',keyboard,true);await nextTick();search.value?.focus()})
onBeforeUnmount(()=>{document.removeEventListener('keydown',keyboard,true);releaseInert();document.body.style.overflow=overflow;if(origin?.isConnected)origin.focus({preventScroll:true})})
</script>
<template><Teleport to="body"><div class="organization-backdrop" @click.self="close"><section ref="panel" class="organization-dialog" role="dialog" aria-modal="true" :aria-label="title" tabindex="-1"><header><h2>{{title}}</h2><button aria-label="关闭移动窗口" :disabled="busy" @click="close">×</button></header><p class="current">{{current}}</p><fieldset :disabled="busy"><label>目标作用域<select :value="scope" aria-label="目标作用域" @change="emit('scope',($event.target as HTMLSelectElement).value)"><option v-if="!scope" disabled value="">请选择领域 / 项目</option><option v-for="item in scopes" :key="item.key" :value="item.key">{{item.label}}</option></select></label><label>搜索目录<input ref="search" v-model="query" aria-label="搜索目标目录" placeholder="搜索名称或完整路径" /></label><div v-if="recent?.length" class="recent"><strong>最近目标</strong><button v-for="row in recent" :key="row.uid" type="button" @click="emit('target',row.uid)">{{row.label}}</button><button type="button" @click="emit('clearRecent')">清除最近目标</button></div><div class="targets" role="group" aria-label="目标目录"><button v-for="row in visible" :key="row.uid" type="button" :disabled="row.disabled||!scope" :class="{selected:target===row.uid}" :aria-pressed="target===row.uid" @click="emit('target',row.uid)">{{row.label}}</button><p v-if="!visible.length">没有匹配的目录</p></div><div v-if="canCreate&&scope" class="create"><input v-model="name" aria-label="新目录名称" placeholder="在目标作用域新建顶级目录" maxlength="120"/><button type="button" :disabled="!name.trim()" @click="emit('create',name.trim())">新建并选中</button></div></fieldset><p class="impact">{{impact}}</p><slot name="preview"/><div v-if="errors.length" class="errors" role="alert"><p v-for="(error,index) in errors" :key="index">{{error}}</p></div><footer><button :disabled="busy" @click="close">取消</button><button class="primary-action" :disabled="busy||!scope" @click="emit('submit')">{{busy?'处理中…':submitLabel||(errors.length?'重试失败项':'确认移动')}}</button></footer></section></div></Teleport></template>
<style scoped>
.organization-backdrop{position:fixed;inset:0;z-index:180;display:grid;place-items:center;padding:20px;background:#13271f66}.organization-dialog{box-sizing:border-box;width:min(620px,100%);max-height:calc(100dvh - 40px);overflow:auto;padding:22px;border-radius:14px;background:#fff;color:var(--pc-text);box-shadow:0 20px 70px #14251b40;font-size:13px;overscroll-behavior:contain}.organization-dialog header,.organization-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.organization-dialog h2{font-size:18px;margin:0}.organization-dialog button{min-height:36px;padding:7px 12px;border:1px solid var(--pc-border);border-radius:7px;background:#fff;color:inherit;cursor:pointer}.organization-dialog button:disabled{opacity:.5;cursor:default}.organization-dialog fieldset{min-width:0;margin:0;padding:0;border:0}.organization-dialog label{display:grid;gap:6px;margin:12px 0}.organization-dialog input,.organization-dialog select{box-sizing:border-box;width:100%;min-height:36px;padding:7px;border:1px solid var(--pc-border);border-radius:7px;background:#fff;color:inherit}.targets{display:grid;gap:5px;max-height:240px;overflow:auto;border:1px solid var(--pc-border);padding:7px;border-radius:8px}.targets button{text-align:left;overflow-wrap:anywhere}.targets button.selected{background:var(--pc-primary-soft);border-color:var(--pc-primary);color:var(--pc-primary)}.current,.impact{line-height:1.6;overflow-wrap:anywhere;color:var(--pc-muted)}.errors{max-height:140px;overflow:auto;padding:8px;color:#a13e32;background:#fff1ee;overflow-wrap:anywhere}.errors p{margin:4px}.create{display:flex;gap:7px;margin-top:10px}.create button{flex:none}.recent{display:flex;flex-wrap:wrap;gap:5px;margin:8px 0}.recent strong{width:100%;font-size:12px}.recent button{max-width:100%;overflow-wrap:anywhere;font-size:12px}.organization-dialog footer{justify-content:flex-end;margin-top:16px}.organization-dialog .primary-action{background:var(--pc-primary);color:#fff}
</style>
